pub(crate) struct Fragment {
    pub index: u32,
    pub id: Option<String>,
    pub ty: Option<String>,
    pub function: Option<NameArgs>,
    pub custom: Option<NameArgs>,
    /// The whole entry, for kind Other (§ 4.1).
    pub raw: Value,
}

pub(crate) struct NameArgs {
    pub name: Option<String>,
    pub args: Option<String>,

/// A tool-call entry at a known `index`. A non-stream body has no per-entry `index`, so its
/// array position stands in (spec § 4.2).
pub(crate) fn fragment_at(v: &Value, index: u32) -> Result<Fragment, Malformed> {
    let Value::Object(e) = v else { return Err(Malformed("tool_call")) };
    let id = opt_str(e.get("id"), "id")?;
    let ty = opt_str(e.get("type"), "type")?;
    let function = opt_obj(e.get("function"), "function")?.map(|f| name_args(f, "arguments")).transpose()?;
    let custom = opt_obj(e.get("custom"), "custom")?.map(|f| name_args(f, "input")).transpose()?;
    if function.is_some() && custom.is_some() {
        return Err(Malformed("function_and_custom"));
    }
    Ok(Fragment {
        index,
        id,
        ty,
        function,
        custom,
        raw: v.clone(),
    })
}

pub(crate) fn name_args(f: &Map<String, Value>, args_key: &'static str) -> Result<NameArgs, Malformed> {
    Ok(NameArgs {
        name: opt_str(f.get("name"), "name")?,
        if let Some(l) = legacy {
            long_check(None, l.name.as_deref())?;
            once(self.legacy.get_or_insert(false), l.name.is_some(), "repeated_name")?;
        }
        let before = self.calls.len();
        if let Some(n) = self.bodyless_at {
            if frags.iter().any(|f| (f.index as usize) < n) {
                return Err(Deviation("fragment_after_bodyless_entry"));
            }
        } else if frags.iter().any(|f| f.function.is_none()) {
            if frags.iter().any(|f| (f.index as usize) < before) {
                return Err(Deviation("fragment_after_bodyless_entry"));
            }
            self.bodyless_at = Some(before);
        }
        for f in frags {
            let pos = f.index as usize;
            if pos == self.calls.len() {
                self.calls.push(Shadow::default());
            } else if pos > self.calls.len() {
                return Err(Deviation("index_gap"));
            }
            let b = &mut self.calls[pos];
            long_check(f.id.as_deref(), f.function.as_ref().or(f.custom.as_ref()).and_then(|na| na.name.as_deref()))?;
            once(&mut b.id, f.id.is_some(), "repeated_id")?;
            if let Some(t) = &f.ty {
                // The type names a bodyless Other call, so it is bounded like an id or a name.
                long_check(Some(t), None)?;
                if b.ty.is_some() {
                    return Err(Deviation("repeated_type"));
                }
                b.ty = Some(match t.as_str() {
                    "function" => TyClass::Function,
                    "custom" => TyClass::Custom,
                    _ => TyClass::Other,
                });
            }
            let (shape, na) = match (&f.function, &f.custom) {
                (Some(na), None) => (Some(Shape::Function), Some(na)),
                (None, Some(na)) => (Some(Shape::Custom), Some(na)),
                _ => (None, None),
            };
            if let Some(s) = shape {
                match b.shape {
                    None => b.shape = Some(s),
                    Some(prev) if prev != s => return Err(Deviation("shape_changed")),
                    Some(_) => {}
                }
            }
            if let Some(na) = na {
                once(&mut b.name, na.name.is_some(), "repeated_name")?;
            }
        }
        Ok(())
    }

    /// The kind of every call once the choice finishes, or the deviation that finishing is.
    pub(crate) fn finish(&self) -> Result<Vec<ToolCallKind>, Deviation> {
        if let Some(has_name) = self.legacy {
            if !has_name {
                return Err(Deviation("missing_name"));
            }
            return Ok(vec![ToolCallKind::LegacyFunctionCall]);
        }
        self.calls
            .iter()
            .map(|b| {
                // Clients ignore `type` and run the body, so any type other than the one the
                // body's shape expects is a deviation, never kind Other (spec I1).
                let kind = match (b.shape, b.ty) {
                    (Some(Shape::Function), Some(TyClass::Function) | None) => ToolCallKind::Function,
                    (Some(Shape::Custom), Some(TyClass::Custom) | None) => ToolCallKind::Custom,
                    (Some(_), Some(_)) => return Err(Deviation("type_shape_mismatch")),
                    (None, Some(TyClass::Function | TyClass::Custom)) => return Err(Deviation("missing_body")),
                    (None, _) => ToolCallKind::Other,
                };
                if kind != ToolCallKind::Other && !b.name {
                    return Err(Deviation("missing_name"));
                }
                Ok(kind)
            })
            .collect()
    }
}

