        body.truncate(body.trim_end_matches('\n').len());
    }
    if has(s, Quirk::JsonBody).is_some() {
        body = json!({"choices":[{"index":0,"message":{"tool_calls":[{"id":"c","type":"function","function":{"name":"blocked_json","arguments":"CANARY-json"}}]}}]}).to_string();
    }
    body.into_bytes()
}

